args.ReplacementContent:
useEffect(() => {
  const handleTourDropdownsOutside = (e: MouseEvent) => {
    const target = e.target as HTMLElement;
    if (!target.closest('[data-tour-dropdown]')) {
      setShowTourDropdown(false);
    }
    if (!target.closest('[data-tour-dates-dropdown]')) {
      setShowTourDatesDropdown(false);
    }
    if (!target.closest('[data-group-popover-cell]')) {
      setCellGroupPopover(null);
    }
  };
  document.addEventListener('mousedown', handleTourDropdownsOutside);
  return () => document.removeEventListener('mousedown', handleTourDropdownsOutside);
}, []);

